package com.trident.security;
import org.springframework.context.annotation.*;import org.springframework.http.HttpMethod;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.cors.*;import org.springframework.web.cors.UrlBasedCorsConfigurationSource;import java.util.List;
@Configuration
public class SecurityConfig {
 private final JwtAuthFilter filter;public SecurityConfig(JwtAuthFilter filter){this.filter=filter;}
 @Bean SecurityFilterChain chain(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/error").permitAll().requestMatchers(HttpMethod.GET,"/api/jobs/mine").hasAnyRole("RECRUITER","ADMIN").requestMatchers(HttpMethod.GET,"/api/jobs/**").permitAll().requestMatchers(HttpMethod.POST,"/api/jobs").hasAnyRole("RECRUITER","ADMIN").requestMatchers(HttpMethod.PUT,"/api/jobs/**").hasAnyRole("RECRUITER","ADMIN").requestMatchers(HttpMethod.DELETE,"/api/jobs/**").hasAnyRole("RECRUITER","ADMIN").anyRequest().authenticated()).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();}
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean CorsConfigurationSource cors(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOriginPatterns(List.of("http://localhost:*","http://127.0.0.1:*"));c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
}